def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    y = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not y:
        return [0.0] * horizon
    p = 7 if 'day' in frequency.lower() else 1
    if len(y) < 2 * p:
        return [y[-1]] * horizon

    def predict(train, steps, cycles, alpha, use_trend):
        n = len(train)
        phase_values = []
        for ph in range(p):
            vals = [train[i] for i in range(ph, n, p)][-cycles:]
            phase_values.append(vals)
        blocks = len(train) // p
        levels = []
        for k in range(max(0, blocks - cycles), blocks):
            block = train[k * p:(k + 1) * p]
            if block:
                levels.append(float(statistics.median(block)))
        slopes = []
        for i in range(len(levels)):
            for j in range(i + 1, len(levels)):
                slopes.append((levels[j] - levels[i]) / (j - i))
        drift = float(statistics.median(slopes)) if use_trend and slopes else 0.0
        changes = [abs(levels[i] - levels[i - 1]) for i in range(1, len(levels))]
        cap = float(statistics.median(changes)) if changes else 0.0
        drift = max(-cap, min(cap, drift)) if cap > 0.0 else 0.0
        out = []
        for t in range(steps):
            ph = (n + t) % p
            vals = phase_values[ph]
            if vals:
                recent = vals[-1]
                stable = float(statistics.median(vals))
                value = alpha * recent + (1.0 - alpha) * stable
            else:
                value = train[-1]
            if use_trend:
                age = (t + 1.0) / p
                value += drift * 3.0 * (1.0 - math.exp(-age / 3.0))
            out.append(float(value))
        return out

    candidates = []
    for cycles in (3, 5, 8, 12):
        for alpha in (0.0, 0.25, 0.5, 0.75, 1.0):
            for use_trend in (False, True):
                candidates.append((cycles, alpha, use_trend))
    origins = list(range(max(2 * p, len(y) - 7 * p), len(y) - p + 1, p))
    best = candidates[0]
    best_score = float('inf')
    for candidate in candidates:
        errors = []
        for origin in origins:
            pred = predict(y[:origin], p, *candidate)
            actual = y[origin:origin + p]
            for a, f in zip(actual, pred):
                denom = abs(a) + abs(f)
                errors.append(0.0 if denom == 0.0 else 200.0 * abs(a - f) / denom)
        score = sum(errors) / len(errors) if errors else float('inf')
        if score < best_score:
            best_score = score
            best = candidate
    result = predict(y, horizon, *best)
    return [v if math.isfinite(v) else y[-1] for v in result]
